verify:
choices = {o: choices[n] for o, n in {'B': 'A', 'D': 'B', 'A': 'C', 'C': 'D'}.items()}; answer = {'A': 'B', 'B': 'D', 'C': 'A', 'D': 'C'}[answer]  # shuffled: original letters
def pair(s):
    a, b = s.replace('\\(', '').replace('\\)', '').strip('() ').split(',')
    return (value(a), value(b))
x, y = symbols('x y')
sols = {(s[x], s[y]) for s in solve([Eq(y, x**2 - 1), Eq(y, 3)], [x, y], dict=True)}
assert sols == {(2, 3), (-2, 3)}
assert pair(choices[answer]) in sols
assert all(pair(choices[k]) not in sols for k in choices if k != answer)
